@PostMapping("/orders")
ResponseEntity<OrderDto> create(@RequestBody OrderCmd cmd) {
    OrderDto saved = orders.create(cmd);                 // producer
    URI location = ServletUriComponentsBuilder.fromCurrentContextPath()
            .path("/orders/{id}").buildAndExpand(saved.id()).toUri();
    return ResponseEntity.created(location).body(saved); // consumer GETs location next
}
